# owner: platform
import unittest

from hourglass.rounding import label_spans
from hourglass.models import Span

class LabelTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [Span(9 * 60 + 4, 17 * 60 + 11)]
        self.assertEqual(
            label_spans(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_rounds_up(self):
        spans = [Span(60, 125)]
        self.assertEqual(
            label_spans(spans, 10),
            ["01:00-02:10 (1h 10m)"]
        )

    def test_several_spans(self):
        spans = [Span(0, 60), Span(480, 1440)]
        self.assertEqual(
            label_spans(spans, 30),
            ["00:00-01:00 (1h 0m)", "08:00-24:00 (16h 0m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.assertRaises(ValueError):
                label_spans([Span(0, 60)], step)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            label_spans([Span(541, 545)], 15)
